/**
 * Fill-later substrate so a teams-and-coaches roster can still Plan.
 * Does not invent kids or extra teams. NTSSA clocks, a pitch to sit on,
 * and the Fall 2026 window stay flagged as holes.
 */

import { ensureOpenDays } from "./calendar";
import { resolveClock, stampClock } from "./clock";
import { formatClockShort, parseAvailability, parseClock } from "./dates";
import { NTSSA_AGE_GROUPS, NTSSA_FIELD_TYPES } from "./fake-league";
import { isHomeWizardPitch } from "./fields";
import { norm, type AgeGroup, type League, type PreferredSlot } from "./model";

export function normalizeBracket(raw: string): string {
  const s = String(raw || "").trim();
  if (!s) return "";
  const uFirst = s.match(/^u\s*(\d+)$/i);
  if (uFirst) return `${uFirst[1]}U`;
  const nU = s.match(/^(\d+)\s*u$/i);
  if (nU) return `${nU[1]}U`;
  if (/^ll$|learner/i.test(s)) return "LL";
  return s;
}

export function ntssaSpec(bracket: string): AgeGroup {
  const n = normalizeBracket(bracket) || bracket;
  if (n === "LL") {
    const six = NTSSA_AGE_GROUPS.find((a) => a.name === "6U")!;
    return { ...six, name: "LL", mayPlayWith: ["LL"], assumed: true };
  }
  const hit = NTSSA_AGE_GROUPS.find((a) => norm(a.name) === norm(n));
  if (hit) return { ...hit, name: n, mayPlayWith: [n], assumed: true };
  const six = NTSSA_AGE_GROUPS.find((a) => a.name === "6U")!;
  return { ...six, name: n, mayPlayWith: [n], assumed: true };
}

function addAssumedFields(league: League) {
  const classes = new Set(league.ageGroups.flatMap((a) => a.fieldClasses.map((c) => norm(c))));
  if (!classes.size) classes.add("small");
  const need: Record<string, number> = { small: 3, medium: 2, nine: 1, full: 1 };
  const letters = ["A", "B", "C", "D", "E", "F", "G", "H"];
  let i = 0;
  const availableRaw = "Saturday 8:00–18:00";
  const windows = parseAvailability(availableRaw);
  league.fields = [];
  for (const cls of ["small", "medium", "nine", "full"]) {
    if (!classes.has(cls)) continue;
    const n = need[cls] || 1;
    for (let k = 0; k < n; k++) {
      league.fields.push({
        name: `Not listed yet ${letters[i++] || i}`,
        type: cls,
        campus: "Van Complex",
        parking: "",
        availableRaw,
        windows,
        assumed: true,
      });
    }
  }
}

/** Keep named home pitches; park Plan on Not listed yet if none remain. Guest-campus grass stays. */
export function ensurePlaceholderGrass(league: League): League {
  const guest = league.fields.filter((f) => !isHomeWizardPitch(league, f));
  const realHome = league.fields.filter((f) => isHomeWizardPitch(league, f) && !f.assumed);
  if (realHome.length) {
    league.fields = [...realHome, ...guest];
    return league;
  }
  addAssumedFields(league);
  league.fields.push(...guest);
  return league;
}

/** Mutates `league`: NTSSA clocks, placeholder grass, Fall 2026 window if blank. */
export function fillPlanningHoles(league: League): League {
  for (const ag of league.ageGroups) {
    const spec = ntssaSpec(ag.name);
    let filled = false;
    if (ag.minOnField == null) {
      ag.minOnField = spec.minOnField;
      filled = true;
    }
    if (ag.maxOnField == null) {
      ag.maxOnField = spec.maxOnField;
      filled = true;
    }
    if (ag.gameLengthMinutes == null) {
      ag.gameLengthMinutes = spec.gameLengthMinutes;
      filled = true;
    }
    if (ag.firstHalfMinutes == null || ag.halfTimeMinutes == null || ag.warmupMinutes == null) {
      stampClock(ag, resolveClock(ag));
      filled = true;
    }
    if (ag.assistantMin == null) {
      ag.assistantMin = spec.assistantMin;
      filled = true;
    }
    if (ag.assistantPreferred == null) {
      ag.assistantPreferred = spec.assistantPreferred;
      filled = true;
    }
    if (!ag.fieldClasses.length) {
      ag.fieldClasses = [...spec.fieldClasses];
      filled = true;
    }
    if (!ag.mayPlayWith.length) ag.mayPlayWith = [ag.name];
    if (filled) ag.assumed = true;
  }

  if (!league.fieldTypes.length) {
    league.fieldTypes = NTSSA_FIELD_TYPES.map((t) => ({ ...t }));
  }

  ensurePlaceholderGrass(league);

  if (!league.campuses.length) {
    league.campuses.push({
      name: "Van Complex",
      association: "Van Rec",
      street: "445 S Oak St, Van, TX 75790",
      lat: 32.5243,
      lng: -95.6374,
    });
  }
  if (!league.associations.length) {
    league.associations.push({ name: "Van Rec", controlled: true, homeCampus: "Van Complex", guestSides: [] });
  }
  for (const t of league.teams) {
    if (!t.association) t.association = "Van Rec";
  }

  if (!league.season.associationName) league.season.associationName = "Van Soccer Association";
  if (!league.season.title) league.season.title = "Fall 2026";
  if (!league.season.headerTitle) league.season.headerTitle = "Fall 2026";
  if (!league.season.weekStarts) league.season.weekStarts = "Saturday";
  if (!league.season.rematchCap) league.season.rematchCap = 2;
  if (!league.season.firstIso || !league.season.lastIso) {
    league.season.firstIso = "2026-08-23";
    league.season.lastIso = "2026-11-14";
    if (!league.season.firstRaw) league.season.firstRaw = "Saturday, August 23";
    if (!league.season.lastRaw) league.season.lastRaw = "Saturday, November 14";
    league.season.assumedWindow = true;
  }
  ensurePreferredSlots(league);
  ensureOpenDays(league);
  return league;
}

function ageYears(bracket: string): number {
  const m = String(bracket || "").match(/(\d+)\s*U/i) || String(bracket || "").match(/^U\s*(\d+)/i);
  return m ? Number(m[1]) : 6;
}

function minutesOf(raw: string, fallback: number): number {
  let n = parseClock(raw) ?? fallback;
  if (n < 7 * 60) n += 12 * 60;
  return n;
}

/** Little kids in the morning. 16U may start at 2:00; 6U must not. */
export function defaultPreferredSlot(bracket: string): PreferredSlot {
  const n = ageYears(bracket);
  let time = "8:00";
  if (n <= 6) time = "8:00";
  else if (n <= 8) time = "8:30";
  else if (n <= 10) time = "9:30";
  else if (n <= 12) time = "10:30";
  else if (n <= 14) time = "12:00";
  else time = "14:00";
  return { bracket, rank: 1, day: "Saturday", time };
}

/** Rank-1 slot for a league, or the age default. Does not invent extra ranks. */
export function preferredFor(league: League, bracket: string): PreferredSlot {
  const hit = league.preferredSlots
    .filter((p) => norm(p.bracket) === norm(bracket))
    .sort((a, b) => a.rank - b.rank)[0];
  return hit ? { ...hit } : defaultPreferredSlot(bracket);
}

function uniqueSortedTimes(raw: string[]): string[] {
  const seen = new Set<number>();
  const items: { m: number; t: string }[] = [];
  for (const t of raw) {
    const parsed = parseClock(t);
    if (parsed == null) continue;
    let m = parsed;
    if (m < 7 * 60) m += 12 * 60;
    if (seen.has(m)) continue;
    seen.add(m);
    items.push({ m, t: t.trim() });
  }
  items.sort((a, b) => a.m - b.m);
  return items.map((i) => i.t);
}

/** Saturday home kickoffs for a league — named list, else Preferred slots. */
export function homeKickoffsFor(league: League, bracket: string): string[] {
  const ag = league.ageGroups.find((a) => norm(a.name) === norm(bracket));
  if (ag?.homeKickoffs) return uniqueSortedTimes(ag.homeKickoffs);
  return uniqueSortedTimes(
    league.preferredSlots
      .filter((p) => norm(p.bracket) === norm(bracket) && p.day.toLowerCase() === "saturday")
      .sort((a, b) => a.rank - b.rank)
      .map((p) => p.time),
  );
}

/** Write Saturday home kickoffs onto the age group and Preferred slots. */
export function setHomeKickoffs(league: League, bracket: string, times: string[]): string[] {
  const sat = uniqueSortedTimes(times);
  const ag = league.ageGroups.find((a) => norm(a.name) === norm(bracket));
  if (ag) ag.homeKickoffs = sat;
  const keep = league.preferredSlots.filter(
    (p) => !(norm(p.bracket) === norm(bracket) && p.day.toLowerCase() === "saturday"),
  );
  const oldSat = league.preferredSlots.filter(
    (p) => norm(p.bracket) === norm(bracket) && p.day.toLowerCase() === "saturday",
  );
  const next: PreferredSlot[] = sat.map((time, i) => {
    const prev = oldSat.find((p) => minutesOf(p.time, -1) === minutesOf(time, -1));
    return { bracket, rank: i + 1, day: "Saturday", time, venue: prev?.venue };
  });
  league.preferredSlots = [...keep, ...next];
  return sat;
}

export function addHomeKickoff(league: League, bracket: string, raw: string): boolean {
  const mins = parseClock(raw);
  if (mins == null) return false;
  const clock = formatClockShort(mins);
  const have = homeKickoffsFor(league, bracket);
  if (have.some((t) => minutesOf(t, -1) === minutesOf(clock, -1))) {
    setHomeKickoffs(league, bracket, have);
    return true;
  }
  setHomeKickoffs(league, bracket, [...have, clock]);
  return true;
}

export function removeHomeKickoff(league: League, bracket: string, raw: string): boolean {
  if (parseClock(raw) == null) return false;
  const want = minutesOf(raw, -1);
  const have = homeKickoffsFor(league, bracket);
  const next = have.filter((t) => minutesOf(t, -1) !== want);
  if (next.length === have.length) return false;
  setHomeKickoffs(league, bracket, next);
  return true;
}

/** Seed one preferred day+start per league when the workbook did not name any. */
export function ensurePreferredSlots(league: League): void {
  const have = new Set(league.preferredSlots.map((p) => norm(p.bracket)));
  for (const ag of league.ageGroups) {
    if (!ag.name) continue;
    if (ag.homeKickoffs !== undefined) {
      setHomeKickoffs(league, ag.name, ag.homeKickoffs);
      have.add(norm(ag.name));
      continue;
    }
    if (have.has(norm(ag.name))) continue;
    const slot = defaultPreferredSlot(ag.name);
    league.preferredSlots.push(slot);
    ag.homeKickoffs = [slot.time];
    have.add(norm(ag.name));
  }
}

export function upsertPreferred(
  league: League,
  bracket: string,
  patch: { day?: string; time?: string },
): PreferredSlot {
  const hits = league.preferredSlots
    .filter((p) => norm(p.bracket) === norm(bracket))
    .sort((a, b) => a.rank - b.rank);
  let row = hits[0];
  if (!row) {
    row = defaultPreferredSlot(bracket);
    league.preferredSlots.push(row);
  }
  if (patch.day) row.day = patch.day;
  if (patch.time) row.time = patch.time;
  if (!row.rank) row.rank = 1;
  return row;
}

/**
 * Soft packing cost for a kickoff. Exact preferred ranks win; later than the
 * league's start is expensive so 6U does not land at 2:00 unless nothing else fits.
 * A named list of two or more Saturday starts is a menu: listed times win, others sit far back.
 */
export function preferredKickCost(league: League, bracket: string, minutes: number, day = "saturday"): number {
  const named = day.toLowerCase() === "saturday" ? homeKickoffsFor(league, bracket) : [];
  if (day.toLowerCase() === "saturday" && named.length === 0) {
    const ag = league.ageGroups.find((a) => norm(a.name) === norm(bracket));
    if (ag?.homeKickoffs) return 0;
  }
  const hits = league.preferredSlots
    .filter((p) => norm(p.bracket) === norm(bracket) && String(p.time || "").trim())
    .sort((a, b) => a.rank - b.rank);
  if (!hits.length && !named.length) return 0;
  const sameDay = named.length && day.toLowerCase() === "saturday"
    ? named.map((time, i) => ({ time, rank: i + 1, day: "Saturday", bracket }))
    : hits.filter((p) => p.day.toLowerCase() === day.toLowerCase());
  const exact = sameDay.find((p) => minutesOf(p.time, -1) === minutes);
  if (exact) return (exact.rank - 1) * 8;
  if (!sameDay.length) return 80;
  if (sameDay.length >= 2) return 100;
  const start = minutesOf(sameDay[0].time, 9 * 60);
  const delta = minutes - start;
  if (delta === 0) return 0;
  if (delta < 0) return Math.ceil(-delta / 15) * 3;
  return Math.ceil(delta / 15) * 6;
}

export function prepareForPlanning(league: League): League {
  return fillPlanningHoles(structuredClone(league));
}
