import { crowFliesMinutes } from "./haversine";
import { formatClockShort, parseClock } from "./dates";
import {
  familyLabel,
  norm,
  printName,
  teamLabel,
  type ImportIssue,
  type League,
  type TravelCell,
} from "./model";
import { owedGames } from "./calendar";

function commissionerMinutes(time: string): number | null {
  let n = parseClock(time);
  if (n == null) return null;
  if (n < 7 * 60) n += 12 * 60;
  return n;
}

export const DUMMY_PEOPLE = [
  "Alex Reed",
  "Avery Chen",
  "Jordan Blake",
  "Sam Example",
  "Riley Example",
  "Casey Example",
  "Morgan Example",
  "Quinn Example",
  "Jamie Example",
  "Drew Example",
];

export function isDummyName(name: string): boolean {
  const n = name.trim().toLowerCase();
  if (DUMMY_PEOPLE.some((d) => d.toLowerCase() === n)) return true;
  return /\bexample\b/.test(n) || n === "alex reed";
}

export function campusStreet(league: League, name: string): string | undefined {
  return league.campuses.find((c) => norm(c.name) === norm(name))?.street;
}

export function isGuestCampus(league: League, name: string): boolean {
  const campus = league.campuses.find((c) => norm(c.name) === norm(name));
  if (!campus) return /mineola|forney/i.test(name);
  const assoc = league.associations.find(
    (a) =>
      norm(a.homeCampus || "") === norm(name) ||
      (campus.association && norm(a.name) === norm(campus.association)),
  );
  if (assoc) return !assoc.controlled;
  return /mineola|forney/i.test(name);
}

export function homeCampusName(league: League): string {
  const rec = league.associations.find((a) => a.controlled && /rec/i.test(a.name));
  return rec?.homeCampus || league.campuses.find((c) => /van complex/i.test(c.name))?.name || "Van Complex";
}

export function crossClassPairs(league: League): string[] {
  const out: string[] = [];
  for (const a of league.ageGroups) {
    for (const m of a.mayPlayWith) {
      if (norm(m) === norm(a.name)) continue;
      const b = league.ageGroups.find((x) => norm(x.name) === norm(m));
      if (!b) continue;
      if (!b.mayPlayWith.some((x) => norm(x) === norm(a.name))) continue;
      const key = [a.name, m].sort((x, y) => x.localeCompare(y)).join(" ↔ ");
      if (!out.includes(key)) out.push(key);
    }
  }
  return out;
}

function specialSnapsTo(iso: string, dateIso: string): boolean {
  if (iso === dateIso) return true;
  return Math.abs(Date.parse(`${iso}T00:00:00Z`) - Date.parse(`${dateIso}T00:00:00Z`)) <= 2 * 86400000;
}

export function isHomeGuestDate(league: League, dateIso: string): boolean {
  if ((league.season.homeWeekends || []).some((w) => w.dateIso === dateIso)) return true;
  return league.season.specials.some((s) => {
    if (s.kind !== "interleague-home" || !s.iso) return false;
    return specialSnapsTo(s.iso, dateIso);
  });
}

export function isAwayGuestDate(league: League, dateIso: string): boolean {
  if ((league.season.awayWeekends || []).some((w) => w.dateIso === dateIso)) return true;
  return league.season.specials.some((s) => {
    if (s.kind !== "interleague-away" || !s.iso) return false;
    return specialSnapsTo(s.iso, dateIso);
  });
}

export function travelMinutes(league: League, from: string, to: string): {
  minutes: number | null;
  crowFlies: boolean;
  missing: boolean;
} {
  if (norm(from) === norm(to)) return { minutes: 0, crowFlies: false, missing: false };
  const hit = league.travel.find(
    (t) =>
      (norm(t.from) === norm(from) && norm(t.to) === norm(to)) ||
      (norm(t.from) === norm(to) && norm(t.to) === norm(from)),
  );
  if (hit && hit.minutes != null) return { minutes: hit.minutes, crowFlies: !!hit.crowFlies, missing: false };
  const a = league.campuses.find((c) => norm(c.name) === norm(from));
  const b = league.campuses.find((c) => norm(c.name) === norm(to));
  if (a && b && a.lat != null && a.lng != null && b.lat != null && b.lng != null) {
    return {
      minutes: crowFliesMinutes({ lat: a.lat, lng: a.lng }, { lat: b.lat, lng: b.lng }),
      crowFlies: true,
      missing: false,
    };
  }
  return { minutes: null, crowFlies: false, missing: true };
}

export function fillCrowFlies(league: League): TravelCell[] {
  const names = league.campuses.map((c) => c.name);
  const cells = [...league.travel];
  for (const a of names) {
    for (const b of names) {
      if (a === b) continue;
      const known = cells.find(
        (t) =>
          (norm(t.from) === norm(a) && norm(t.to) === norm(b)) ||
          (norm(t.from) === norm(b) && norm(t.to) === norm(a)),
      );
      if (known && known.minutes != null) continue;
      const guess = travelMinutes({ ...league, travel: cells }, a, b);
      if (guess.minutes != null && guess.crowFlies) {
        cells.push({ from: a, to: b, minutes: guess.minutes, crowFlies: true });
      }
    }
  }
  return cells;
}

export function inspectFlags(league: League): ImportIssue[] {
  const issues: ImportIssue[] = [];
  const types = new Set(league.fieldTypes.map((t) => norm(t.name)));
  const fieldClasses = league.fields.map((f) => norm(f.type));

  for (const ag of league.ageGroups) {
    const legal = ag.fieldClasses.some((c) => fieldClasses.includes(norm(c)));
    if (!legal) {
      issues.push({
        level: "flag",
        code: "no-legal-field",
        message: `${ag.name}: no field of class ${ag.fieldClasses.join(" / ") || "full"} is listed`,
      });
    }
    for (const cls of ag.fieldClasses) {
      if (types.size && !types.has(norm(cls))) {
        issues.push({
          level: "flag",
          code: "unknown-class",
          message: `${ag.name}: field class "${cls}" is not on Field types`,
        });
      }
    }
  }

  for (const campus of league.campuses) {
    const hasAddr = !!(campus.street && campus.street.trim());
    const hasPin = campus.lat != null && campus.lng != null;
    const hasTravel = league.travel.some(
      (t) =>
        (norm(t.from) === norm(campus.name) || norm(t.to) === norm(campus.name)) &&
        t.minutes != null,
    );
    if (!hasAddr && !hasPin && !hasTravel) {
      issues.push({
        level: "flag",
        code: "campus-no-location",
        message: `${campus.name}: No address, no pin, no drive times. Teams cannot be sent here until one of those exists.`,
      });
    }
  }

  for (const team of league.teams) {
    // No names yet is a fill-later hole (missing-players), not "cannot field".
    if (!team.players.length) continue;
    const ag = league.ageGroups.find((a) => norm(a.name) === norm(team.bracket));
    const bracketFloor = ag?.minOnField ?? 0;
    if (bracketFloor && team.players.length < bracketFloor) {
      issues.push({
        level: "flag",
        code: "roster-short",
        message: `${teamLabel(team)}: ${team.players.length} players rostered — ${team.bracket} needs ${bracketFloor} on the field.`,
      });
    } else if (
      team.minOnField &&
      team.players.length < team.minOnField &&
      (!ag?.minOnField || team.minOnField > ag.minOnField)
    ) {
      issues.push({
        level: "flag",
        code: "team-floor",
        message: `${teamLabel(team)}: ${team.players.length} players rostered — this team asked for ${team.minOnField}.`,
      });
    }
  }

  for (const slot of league.preferredSlots) {
    if (!slot.venue) continue;
    const field = league.fields.find(
      (f) => norm(f.name) === norm(slot.venue || "") || norm(f.name).includes(norm(slot.venue || "")),
    );
    if (!field || !field.windows.length) continue;
    const day = slot.day.toLowerCase();
    const win = field.windows.find((w) => w.day === day);
    if (!win) {
      issues.push({
        level: "flag",
        code: "slot-closed",
        message: `${slot.bracket} rank-${slot.rank}: ${field.name} has no ${slot.day} hours`,
      });
      continue;
    }
    const kick = commissionerMinutes(slot.time);
    if (kick != null && kick < win.startMinutes) {
      issues.push({
        level: "flag",
        code: "slot-closed",
        message: `${slot.bracket} rank-${slot.rank}: ${field.name} is closed until ${formatClockShort(win.startMinutes)} ${slot.day}`,
      });
    }
  }

  const vanAssocs = new Set(
    league.associations.filter((a) => a.controlled).map((a) => norm(a.name)),
  );
  const playing = owedGames(league);
  for (const ag of league.ageGroups) {
    const vanTeams = league.teams.filter(
      (t) =>
        norm(t.bracket) === norm(ag.name) &&
        (!vanAssocs.size || vanAssocs.has(norm(t.association))),
    );
    if (vanTeams.length !== 1) continue;
    const guestAsked = league.associations
      .filter((a) => !a.controlled)
      .flatMap((a) => a.guestSides)
      .filter((g) => norm(g.ageGroup) === norm(ag.name))
      .reduce((n, g) => n + (g.gamesRequested || 0), 0);
    if (guestAsked > 0 && guestAsked < playing) {
      issues.push({
        level: "flag",
        code: "guest-short",
        message: `${ag.name} cannot be owed ${playing} against a guest who asked for ${guestAsked}`,
      });
    }
  }
  const tenU = league.teams.filter((t) => norm(t.bracket) === "10u");
  if (tenU.length >= 3 && league.season.rematchCap > 0) {
    const maxWithoutGuest = 2 * (tenU.length - 1);
    // with 3 clubs, each plays 2 others; 12 weeks → some pairs meet 4 times
    const meetingsNeeded = playing;
    const pairs = (tenU.length * (tenU.length - 1)) / 2;
    if (pairs > 0) {
      const minMax = Math.ceil((meetingsNeeded * tenU.length) / (2 * pairs) - 1e-9);
      if (minMax > league.season.rematchCap) {
        issues.push({
          level: "flag",
          code: "rematch-pressure",
          message: `10U rematch pressure: with ${tenU.length} clubs and ${playing} weeks, some pairs will meet ${minMax} times if they stay inside Van. Cap is ${league.season.rematchCap} — this cannot close.`,
        });
      }
    }
  }

  return issues;
}

export function leftoverDummyIssues(league: League): ImportIssue[] {
  const sampleRows =
    league.teams.some((t) => t.sample) ||
    league.families.some((f) => f.sample) ||
    league.staff.some((s) => s.sample);
  const realRows =
    league.teams.some((t) => !t.sample) ||
    league.families.some((f) => !f.sample) ||
    league.staff.some((s) => !s.sample);

  const dummyStaff = league.staff.filter((s) => s.sample || isDummyName(printName(s)));
  const dummyTeams = league.teams.filter((t) => t.sample);
  const dummyFamilies = league.families.filter((f) => f.sample || f.children.some((c) => isDummyName(printName(c))));

  const hasRealPeople =
    league.families.some((f) => !f.sample && f.parents.some((p) => !isDummyName(printName(p)))) ||
    league.staff.some((s) => !s.sample && !isDummyName(printName(s)));

  if ((sampleRows && realRows && hasRealPeople) || (hasRealPeople && dummyStaff.length && dummyFamilies.length === 0 && league.families.some((f) => !f.sample))) {
    const leftovers = [
      ...dummyStaff.map((s) => `Staff ${printName(s)}`),
      ...dummyTeams.map((t) => `Team ${teamLabel(t)}`),
      ...dummyFamilies.map((f) => `Family ${familyLabel(f)}`),
    ];
    if (leftovers.length) {
      return [
        {
          level: "refuse",
          code: "leftover-sample",
          message: `Leftover sample rows still in the workbook: ${leftovers.join(", ")}. Replace or delete every sample row before mixing in your league.`,
        },
      ];
    }
  }
  return [];
}

export function structuralRefusals(league: League): ImportIssue[] {
  const issues: ImportIssue[] = [];

  const seen = new Map<string, number>();
  for (const t of league.teams) {
    const k = teamLabel(t).toLowerCase();
    seen.set(k, (seen.get(k) || 0) + 1);
  }
  for (const [k, n] of seen) {
    if (n > 1) {
      const shown = league.teams.find((t) => teamLabel(t).toLowerCase() === k);
      issues.push({
        level: "refuse",
        code: "duplicate-team",
        message: `Teams: two blocks are both ${shown ? teamLabel(shown) : k}. Change a name (Hedgehogs Black / Hedgehogs Green) or a bracket. Name plus bracket must be unique.`,
      });
    }
  }

  // family collisions: same parent names, no phone, no code
  const buckets = new Map<string, typeof league.families>();
  for (const f of league.families) {
    const names = f.parents
      .map((p) => `${norm(p.first)} ${norm(p.last)}`)
      .filter((n) => n.trim())
      .sort()
      .join("|");
    const phones = f.parents.map((p) => (p.phone || "").replace(/\D/g, "")).filter(Boolean);
    if (!names) continue;
    if (phones.length || (f.code || "").trim()) continue;
    const arr = buckets.get(names) || [];
    arr.push(f);
    buckets.set(names, arr);
  }
  for (const [names, arr] of buckets) {
    if (arr.length > 1) {
      const pretty = names
        .split("|")
        .map((n) => n.replace(/\b\w/g, (c) => c.toUpperCase()))
        .join(" / ");
      issues.push({
        level: "refuse",
        code: "family-collision",
        message: `Families: two rows share ${pretty} with no phone and no family code. Give each parent a phone, or fill Family code (for example SMITH-A and SMITH-B).`,
      });
    }
  }

  // player on two teams
  const kidTeams = new Map<string, Set<string>>();
  const consider = (name: string, team: string) => {
    const k = norm(name);
    if (!k) return;
    const set = kidTeams.get(k) || new Set();
    set.add(team);
    kidTeams.set(k, set);
  };
  for (const f of league.families) {
    for (const c of f.children) {
      consider(printName(c), teamLabel({ name: c.team, bracket: c.bracket }));
    }
  }
  for (const t of league.teams) {
    for (const p of t.players) consider(p.name, teamLabel(t));
  }
  for (const [name, teams] of kidTeams) {
    if (teams.size > 1) {
      const pretty = name.replace(/\b\w/g, (c) => c.toUpperCase());
      issues.push({
        level: "refuse",
        code: "player-two-teams",
        message: `${pretty} appears on ${[...teams].join(" and ")}. This season a player has one team. Remove one listing.`,
      });
    }
  }

  for (const ag of league.ageGroups) {
    const missing: string[] = [];
    if (ag.gameLengthMinutes == null) missing.push("game length");
    if (ag.minOnField == null) missing.push("minimum on the field");
    if (ag.assistantMin == null) missing.push("assistant referees");
    if (missing.length && ag.name) {
      issues.push({
        level: "refuse",
        code: "age-group-incomplete",
        message: `Age groups: ${ag.name} is missing ${joinAnd(missing)}. Fill those cells or delete the row.`,
      });
    }
  }

  issues.push(...leftoverDummyIssues(league));
  return issues;
}

function joinAnd(xs: string[]): string {
  if (xs.length <= 1) return xs[0] || "";
  if (xs.length === 2) return `${xs[0]} and ${xs[1]}`;
  return `${xs.slice(0, -1).join(", ")}, and ${xs[xs.length - 1]}`;
}

/** Holes a commissioner can fill in the UI. Never invent the missing piece. */
export function missingPieceIssues(league: League): ImportIssue[] {
  const issues: ImportIssue[] = [];
  if (!league.ageGroups.length) {
    issues.push({
      level: "flag",
      code: "missing-age-groups",
      message: "No age groups listed. Add 6U / 8U / 10U rows, or fill them in here.",
    });
  }
  const realFields = league.fields.filter((f) => !f.assumed);
  if (!realFields.length) {
    issues.push({
      level: "flag",
      code: "missing-fields",
      message: league.fields.length
        ? "No fields listed. Plan parks on Not listed yet until you add pitches — we did not invent grass."
        : "No fields listed. Add pitches, or fill them in here.",
    });
  }
  if (!league.teams.length) {
    issues.push({
      level: "flag",
      code: "missing-teams",
      message: "No teams listed. We did not invent any.",
    });
  }
  const emptyBrackets = league.ageGroups.filter(
    (ag) => ag.name && !league.teams.some((t) => norm(t.bracket) === norm(ag.name)),
  );
  if (emptyBrackets.length) {
    issues.push({
      level: "flag",
      code: "coach-without-team",
      message: `${emptyBrackets.map((a) => a.name).join(", ")} ${emptyBrackets.length === 1 ? "is" : "are"} on the roster with no team name. We did not invent a side.`,
    });
  }
  if (!league.staff.length && !league.season.proceedWithoutStaff) {
    issues.push({
      level: "flag",
      code: "missing-staff",
      message: "No referees listed. Add staff, or fill them in here.",
    });
  }
  const hollow = league.teams.filter((t) => !t.players.length);
  if (hollow.length && !league.season.proceedWithoutPlayers) {
    issues.push({
      level: "flag",
      code: "missing-players",
      message:
        hollow.length === league.teams.length
          ? "No players listed. Roster holes stay empty until you fill them — we did not invent any kids."
          : `${hollow.map((t) => teamLabel(t)).join(", ")} have no players listed. We did not invent any kids.`,
    });
  }
  if (!league.season.firstIso || !league.season.lastIso || league.season.assumedWindow) {
    issues.push({
      level: "flag",
      code: "missing-season-dates",
      message: league.season.assumedWindow
        ? "Season start and end were blank. Plan uses Saturday, August 23 – Saturday, November 14 until you type dates."
        : "Season start and end are blank. Type them like Sunday, November 8 — we will not guess Saturdays.",
    });
  }
  if (league.campuses.length > 1) {
    const missingTravel = league.campuses.some((from) =>
      league.campuses.some((to) => {
        if (norm(from.name) === norm(to.name)) return false;
        const hit = league.travel.find(
          (t) =>
            (norm(t.from) === norm(from.name) && norm(t.to) === norm(to.name)) ||
            (norm(t.from) === norm(to.name) && norm(t.to) === norm(from.name)),
        );
        return !hit || hit.minutes == null;
      }),
    );
    if (missingTravel) {
      issues.push({
        level: "flag",
        code: "missing-travel",
        message: "Drive times between campuses are missing. Type the minutes you already know.",
      });
    }
  }
  let noPhone = 0;
  for (const s of league.staff) if (!s.phone) noPhone += 1;
  for (const f of league.families) for (const p of f.parents) if (!p.phone) noPhone += 1;
  for (const t of league.teams) {
    if (t.coach && !t.coach.phone) noPhone += 1;
    if (t.assistant && !t.assistant.phone) noPhone += 1;
  }
  if (noPhone) {
    issues.push({
      level: "flag",
      code: "missing-phones",
      message: `${noPhone} ${noPhone === 1 ? "person has" : "people have"} no phone. Add numbers, or fill them in here.`,
    });
  }
  return issues;
}

export function requiredSheetNames(): string[] {
  return [
    "Age groups",
    "Fields",
    "Campuses",
    "Associations",
    "Families",
    "Staff",
    "Teams",
    "Season",
  ];
}

export function generatorChecks(league: League): string[] {
  const errors: string[] = [];
  if (!league.ageGroups.length) errors.push("no age groups");
  if (!league.fields.length) errors.push("no fields");
  if (!league.teams.length) errors.push("no teams");
  if (!league.season.firstIso || !league.season.lastIso) errors.push("season dates missing");
  const keys = new Set<string>();
  for (const t of league.teams) {
    const k = teamLabel(t).toLowerCase();
    if (keys.has(k)) errors.push(`duplicate team ${k}`);
    keys.add(k);
    const ag = league.ageGroups.find((a) => norm(a.name) === norm(t.bracket));
    if (!ag) errors.push(`team ${teamLabel(t)} has unknown bracket`);
    else if (t.players.length > 0 && (ag.minOnField || 0) > t.players.length) {
      errors.push(`team ${teamLabel(t)} below bracket minimum`);
    }
  }
  for (const ag of league.ageGroups) {
    if (ag.gameLengthMinutes == null || ag.minOnField == null || ag.assistantMin == null) {
      errors.push(`age group ${ag.name} incomplete`);
    }
  }
  for (const f of league.fields) {
    if (!f.type || !f.campus) errors.push(`field ${f.name} missing type or campus`);
  }
  const refusals = structuralRefusals(league);
  for (const r of refusals) errors.push(r.message);
  return errors;
}
