/** Shared league vocabulary. Types only — no I/O. */

import type { AssociationSurvey } from "./survey/types";

export interface PersonName {
  first: string;
  last: string;
  printName?: string;
  phone?: string;
}

export interface AgeGroup {
  name: string;
  minOnField: number | null;
  maxOnField: number | null;
  /** Playing minutes (both halves). Kickoff packing uses halves + water + half-time. */
  gameLengthMinutes: number | null;
  warmupMinutes?: number | null;
  firstHalfMinutes?: number | null;
  secondHalfMinutes?: number | null;
  waterBreakMinutes?: number | null;
  halfTimeMinutes?: number | null;
  vacateMinutes?: number | null;
  assistantMin: number | null;
  assistantPreferred: number | null;
  fieldClasses: string[];
  mayPlayWith: string[];
  sample?: boolean;
  /** Clocks / classes filled from NTSSA because the roster did not list them. */
  assumed?: boolean;
  /** Saturday home kickoffs the commissioner named. Empty = any Saturday start. */
  homeKickoffs?: string[];
}

export interface FieldType {
  name: string;
  width: number;
  length: number;
}

export interface TimeWindow {
  day: string;
  startMinutes: number;
  endMinutes: number;
}

export interface Field {
  name: string;
  type: string;
  campus: string;
  parking: string;
  availableRaw: string;
  windows: TimeWindow[];
  sample?: boolean;
  /** Overlay id on the association satellite survey, when this pitch was drawn. */
  surveyOverlayId?: string;
  /** True when this row was created from a survey overlay, not Excel. Delete the overlay and the grass goes with it. */
  surveyCreated?: boolean;
  /** Placeholder pitch so Plan can sit games until the commissioner lists grass. */
  assumed?: boolean;
  /** Wizard sketch map, yards east / south of the complex origin. */
  mapEastYd?: number;
  mapSouthYd?: number;
  headingDeg?: number;
}

export interface Campus {
  name: string;
  association?: string;
  street?: string;
  lat?: number;
  lng?: number;
}

export interface GuestSide {
  ageGroup: string;
  teamCount: number;
  gamesRequested: number;
  name?: string;
  jersey?: string;
}

export interface Association {
  name: string;
  controlled: boolean;
  homeCampus?: string;
  guestSides: GuestSide[];
}

export interface TravelCell {
  from: string;
  to: string;
  minutes?: number;
  crowFlies?: boolean;
}

export interface Parent extends PersonName {
  coachOf: string[];
  assistantOf: string[];
}

export interface Child extends PersonName {
  bracket: string;
  team: string;
  jersey?: string;
}

export interface Family {
  code?: string;
  parents: Parent[];
  children: Child[];
  vacation?: string;
  sample?: boolean;
}

export interface Staff extends PersonName {
  centerOf: string[];
  assistantOf: string[];
  vacation?: string;
  sample?: boolean;
}

export interface TeamAdult extends PersonName {}

export interface TeamPlayer {
  name: string;
  jersey?: string;
  phone?: string;
}

export interface Team {
  name: string;
  bracket: string;
  association: string;
  jersey: string;
  coach?: TeamAdult;
  assistant?: TeamAdult;
  players: TeamPlayer[];
  willNotPlay: string[];
  willNotTravelTo: string[];
  awayDesired: number;
  guestDesired: number;
  guestTravel?: string;
  minOnField?: number;
  sample?: boolean;
}

export interface SpecialDate {
  kind: "bye" | "rain-check" | "interleague-home" | "interleague-away";
  raw: string;
  iso?: string;
  note?: string;
  unreadable?: string;
}

/** One Saturday we travel, or they come here: this league, that other org. */
export interface AwayWeekend {
  dateIso: string;
  association: string;
  bracket: string;
  /** Where the other org plays. */
  campus?: string;
  /** Drive minutes from our home campus. */
  minutes?: number;
}

export type HomeWeekend = AwayWeekend;

/** One day the commissioner marked on the “fields open” calendar. */
export interface OpenDay {
  dateIso: string;
  open: boolean;
  startMinutes: number;
  endMinutes: number;
}

export interface Season {
  associationName: string;
  title: string;
  headerTitle: string;
  weekStarts: string;
  firstRaw: string;
  lastRaw: string;
  firstIso?: string;
  lastIso?: string;
  rematchCap: number;
  specials: SpecialDate[];
  dateFlags: { raw: string; message: string }[];
  /** Fall window used for Plan because the roster left dates blank. */
  assumedWindow?: boolean;
  /** Explicit wizard choice: schedule without player names. */
  proceedWithoutPlayers?: boolean;
  /** Wizard: commissioner saw the no-referees warning. */
  warnedNoStaff?: boolean;
  /** Explicit wizard choice: schedule without named referee staff. */
  proceedWithoutStaff?: boolean;
  /** Wizard: Saturdays we travel, with whom, in which league. */
  awayWeekends?: AwayWeekend[];
  /** Wizard: Saturdays the other league comes HERE. */
  homeWeekends?: HomeWeekend[];
  /** Calendar: which days games may be played, and when grass is open. */
  openDays?: OpenDay[];
  defaultOpenStart?: number;
  defaultOpenEnd?: number;
}

export interface PreferredSlot {
  bracket: string;
  rank: number;
  day: string;
  time: string;
  venue?: string;
}

export interface CarveOut {
  team: string;
  date?: string;
  notAt?: string;
  mustUse?: string;
  everySaturday?: boolean;
}

export interface PlayingWeek {
  startIso: string;
  endIso: string;
  label: string;
  kind: "playing" | "bye" | "rain-check";
  saturdays: string[];
}

export interface League {
  ageGroups: AgeGroup[];
  fieldTypes: FieldType[];
  fields: Field[];
  campuses: Campus[];
  associations: Association[];
  travel: TravelCell[];
  families: Family[];
  staff: Staff[];
  teams: Team[];
  season: Season;
  preferredSlots: PreferredSlot[];
  carveOuts: CarveOut[];
  sourceName?: string;
  sampleOnly?: boolean;
}

export interface ImportIssue {
  level: "refuse" | "warn" | "flag";
  code: string;
  message: string;
}

export interface ImportResult {
  ok: boolean;
  league?: League;
  issues: ImportIssue[];
  report: string[];
  /** Which intake strategy produced this result. */
  strategy?: string;
}

export interface PlacedGame {
  id: string;
  weekIso: string;
  dateIso: string;
  kickoff: string;
  end: string;
  warmupStart: string;
  vacate: string;
  ageGroup: string;
  home: string;
  away: string;
  field: string;
  campus: string;
  parking: string;
  center?: string;
  assistants: string[];
  notes: string[];
  unplayable?: string;
}

export interface ScoreLine {
  key: string;
  text: string;
}

/** One washed playing date pointed at a planted rain-check. */
export interface Washout {
  fromIso: string;
  toIso: string;
  moved: Array<{
    home: string;
    away: string;
    ageGroup: string;
    kickoff: string;
    field: string;
    campus: string;
    parking: string;
    center?: string;
  }>;
  refused: string[];
}

/** Z3 Minimize objective over the whole fall — not last Saturday. */
export interface Z3SeasonScore {
  scope: "season";
  cost: number;
  score: number;
  hardHeld: boolean;
  rematchCost: number;
  grassCost: number;
  travelCost: number;
  householdCost: number;
  hardCost: number;
  brackets: Array<{
    bracket: string;
    cost: number;
    rematch: number;
    grass: number;
    travel: number;
    household: number;
    games: number;
    text: string;
  }>;
  text: string;
}

/** Independent of Z3 and Sims: unique opponents vs possible, rematch histogram. */
export interface DiversityScore {
  score: number;
  uniquePairs: number;
  possiblePairs: number;
  leftoverPairs: Array<{ a: string; b: string }>;
  rematchHistogram: Array<{ meetings: number; pairs: number }>;
  teams: Array<{ team: string; bracket: string; unique: number; possible: number; rematches: number }>;
  brackets: Array<{
    bracket: string;
    uniquePairs: number;
    possiblePairs: number;
    leftover: number;
    score: number;
  }>;
  text: string;
}

/** People-heap after folding. Vocabulary only — the plan lives in folding.ts. */
export interface FoldingSnapshot {
  naiveVars: number;
  foldedVars: number;
  z3Vars: number;
  heap: number;
  bound: number;
  teams: Array<{
    label: string;
    kind: "unit" | "exploded";
    caption: string;
    display: string;
    varCount: number;
    naiveCount: number;
  }>;
  households: Array<{
    last: string;
    label: string;
    kind: "folded" | "exploded";
    caption: string;
    display: string;
    reasons: string[];
  }>;
}

export interface Configuration {
  id: string;
  name: string;
  createdAt: string;
  games: PlacedGame[];
  scores: ScoreLine[];
  hardHeld: boolean;
  diagnostics: string[];
  /** False when the Sims judge refuses the best car/whistle plan. Z3-ok is not enough. */
  simsValid?: boolean;
  /** Always "z3" when Calculate ran. A JS placer must never set this. */
  engine?: "z3";
  z3Verdict?: string;
  z3Probe?: string;
  folding?: FoldingSnapshot;
  stale?: string;
  published?: boolean;
  z3Season?: Z3SeasonScore;
  diversity?: DiversityScore;
  washouts?: Washout[];
}

export interface SeasonState {
  league: League | null;
  configurations: Configuration[];
  publishedId?: string;
  lastSourceName?: string;
  survey?: AssociationSurvey;
}

export function printName(p: PersonName): string {
  const custom = (p.printName || "").trim();
  if (custom) return custom;
  return [p.first, p.last].filter(Boolean).join(" ").trim();
}

export function teamKey(name: string, bracket: string): string {
  return `${bracket.trim()} ${name.trim()}`.replace(/\s+/g, " ");
}

export function teamLabel(t: Pick<Team, "name" | "bracket">): string {
  return teamKey(t.name, t.bracket);
}

export function norm(s: string): string {
  return String(s || "")
    .toLowerCase()
    .replace(/[_./]+/g, " ")
    .replace(/[^a-z0-9]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

export function splitList(raw: string | undefined | null): string[] {
  if (!raw) return [];
  return String(raw)
    .split(/[;,/]| and /i)
    .map((p) => p.trim())
    .filter(Boolean);
}

export function familyLast(f: Family): string {
  return f.parents.find((p) => p.last)?.last || f.children.find((c) => c.last)?.last || "Family";
}

export function familyLabel(f: Family): string {
  const last = familyLast(f);
  const adults = f.parents.map(printName).filter(Boolean).join(", ");
  const kids = f.children
    .map((c) => `${printName(c)} ${c.bracket} ${c.team}`.trim())
    .filter(Boolean)
    .join(", ");
  return `The ${last}s — ${adults}${kids ? " — " + kids : ""}`;
}

/** Stable inspect key — two John Smiths break on phone. */
export function personKey(p: PersonName): string {
  const name = printName(p);
  const phone = (p.phone || "").trim();
  return phone ? `${name}::${phone}` : name;
}

export function parsePersonKey(key: string): { name: string; phone?: string } {
  const i = key.indexOf("::");
  if (i < 0) return { name: key };
  return { name: key.slice(0, i), phone: key.slice(i + 2) };
}

export function familyCardId(f: Family): string {
  const p = f.parents[0];
  if (!p) return familyLast(f);
  return personKey(p);
}
