/** Game occupancy: lead, halves, water breaks, half-time, vacate. */

import type { AgeGroup } from "./model";

export type ClockPart =
  | "warmupMinutes"
  | "firstHalfMinutes"
  | "secondHalfMinutes"
  | "waterBreakMinutes"
  | "halfTimeMinutes"
  | "vacateMinutes";

export interface GameClock {
  warmupMinutes: number;
  firstHalfMinutes: number;
  secondHalfMinutes: number;
  /** Mid-half water. 0 = halves stay solid. Applied once per half. */
  waterBreakMinutes: number;
  halfTimeMinutes: number;
  vacateMinutes: number;
}

export interface ClockSeg {
  id: string;
  part: ClockPart;
  label: string;
  minutes: number;
  kind: "lead" | "play" | "water" | "half" | "after";
}

/** NTSSA/PDI playing time, plus youth breaks so kickoff packing is not a lie. 8U play 40 → 50 on the clock. */
const NTSSA_CLOCK: Record<string, GameClock> = {
  LL: { warmupMinutes: 15, firstHalfMinutes: 16, secondHalfMinutes: 16, waterBreakMinutes: 2, halfTimeMinutes: 4, vacateMinutes: 10 },
  "6U": { warmupMinutes: 15, firstHalfMinutes: 16, secondHalfMinutes: 16, waterBreakMinutes: 2, halfTimeMinutes: 4, vacateMinutes: 10 },
  "8U": { warmupMinutes: 15, firstHalfMinutes: 20, secondHalfMinutes: 20, waterBreakMinutes: 2, halfTimeMinutes: 6, vacateMinutes: 10 },
  "10U": { warmupMinutes: 15, firstHalfMinutes: 25, secondHalfMinutes: 25, waterBreakMinutes: 0, halfTimeMinutes: 5, vacateMinutes: 10 },
  "12U": { warmupMinutes: 15, firstHalfMinutes: 30, secondHalfMinutes: 30, waterBreakMinutes: 0, halfTimeMinutes: 10, vacateMinutes: 10 },
  "14U": { warmupMinutes: 15, firstHalfMinutes: 35, secondHalfMinutes: 35, waterBreakMinutes: 0, halfTimeMinutes: 10, vacateMinutes: 10 },
  "16U": { warmupMinutes: 15, firstHalfMinutes: 40, secondHalfMinutes: 40, waterBreakMinutes: 0, halfTimeMinutes: 10, vacateMinutes: 10 },
};

export function bracketClockKey(raw: string): string {
  const s = String(raw || "").trim();
  const uFirst = s.match(/^u\s*(\d+)/i);
  if (uFirst) return `${uFirst[1]}U`;
  const nU = s.match(/^(\d+)\s*u/i);
  if (nU) return `${nU[1]}U`;
  if (/^ll$|learner/i.test(s)) return "LL";
  const girls = s.match(/^(\d+)\s*u\b/i);
  if (girls) return `${girls[1]}U`;
  return s;
}

export function ntssaClock(bracket: string): GameClock {
  const key = bracketClockKey(bracket);
  const numbered = key.match(/^(\d+)U/i);
  if (numbered && NTSSA_CLOCK[`${numbered[1]}U`]) return { ...NTSSA_CLOCK[`${numbered[1]}U`] };
  if (NTSSA_CLOCK[key]) return { ...NTSSA_CLOCK[key] };
  return { ...NTSSA_CLOCK["6U"] };
}

function num(n: number | null | undefined, fallback: number): number {
  return n == null || !Number.isFinite(n) || n < 0 ? fallback : Math.round(n);
}

export function resolveClock(ag: Pick<AgeGroup, "name" | "gameLengthMinutes" | ClockPart> | undefined | null): GameClock {
  const def = ntssaClock(ag?.name || "6U");
  const play = num(ag?.gameLengthMinutes, def.firstHalfMinutes + def.secondHalfMinutes);
  const first = num(ag?.firstHalfMinutes, Math.floor(play / 2));
  const second = num(ag?.secondHalfMinutes, Math.max(0, play - first));
  return {
    warmupMinutes: num(ag?.warmupMinutes, def.warmupMinutes),
    firstHalfMinutes: first,
    secondHalfMinutes: second,
    waterBreakMinutes: num(ag?.waterBreakMinutes, def.waterBreakMinutes),
    halfTimeMinutes: num(ag?.halfTimeMinutes, def.halfTimeMinutes),
    vacateMinutes: num(ag?.vacateMinutes, def.vacateMinutes),
  };
}

export function playMinutes(c: GameClock): number {
  return c.firstHalfMinutes + c.secondHalfMinutes;
}

/** Kickoff → final whistle, including water and half-time. This is what packing uses. */
export function onClockMinutes(c: GameClock): number {
  const waters = c.waterBreakMinutes > 0 ? 2 * c.waterBreakMinutes : 0;
  return playMinutes(c) + waters + c.halfTimeMinutes;
}

export function occupyMinutes(c: GameClock): number {
  return c.warmupMinutes + onClockMinutes(c) + c.vacateMinutes;
}

export function clockMatchesNtssa(bracket: string, c: GameClock): boolean {
  const spec = ntssaClock(bracket);
  return (
    c.warmupMinutes === spec.warmupMinutes &&
    c.firstHalfMinutes === spec.firstHalfMinutes &&
    c.secondHalfMinutes === spec.secondHalfMinutes &&
    c.waterBreakMinutes === spec.waterBreakMinutes &&
    c.halfTimeMinutes === spec.halfTimeMinutes &&
    c.vacateMinutes === spec.vacateMinutes
  );
}

/** Always draw water as a gutter so it can be pulled open. Halves split around it. */
export function clockSegments(c: GameClock): ClockSeg[] {
  const a1 = Math.floor(c.firstHalfMinutes / 2);
  const a2 = c.firstHalfMinutes - a1;
  const b1 = Math.floor(c.secondHalfMinutes / 2);
  const b2 = c.secondHalfMinutes - b1;
  return [
    { id: "lead", part: "warmupMinutes", label: "lead", minutes: c.warmupMinutes, kind: "lead" },
    { id: "h1a", part: "firstHalfMinutes", label: "1st half", minutes: a1, kind: "play" },
    { id: "w1", part: "waterBreakMinutes", label: "water", minutes: c.waterBreakMinutes, kind: "water" },
    { id: "h1b", part: "firstHalfMinutes", label: "1st half", minutes: a2, kind: "play" },
    { id: "ht", part: "halfTimeMinutes", label: "half", minutes: c.halfTimeMinutes, kind: "half" },
    { id: "h2a", part: "secondHalfMinutes", label: "2nd half", minutes: b1, kind: "play" },
    { id: "w2", part: "waterBreakMinutes", label: "water", minutes: c.waterBreakMinutes, kind: "water" },
    { id: "h2b", part: "secondHalfMinutes", label: "2nd half", minutes: b2, kind: "play" },
    { id: "after", part: "vacateMinutes", label: "after", minutes: c.vacateMinutes, kind: "after" },
  ];
}

export function stampClock(ag: AgeGroup, c: GameClock): void {
  ag.warmupMinutes = c.warmupMinutes;
  ag.firstHalfMinutes = c.firstHalfMinutes;
  ag.secondHalfMinutes = c.secondHalfMinutes;
  ag.waterBreakMinutes = c.waterBreakMinutes;
  ag.halfTimeMinutes = c.halfTimeMinutes;
  ag.vacateMinutes = c.vacateMinutes;
  ag.gameLengthMinutes = playMinutes(c);
}

export function applyClockPart(ag: AgeGroup, part: ClockPart | "gameLengthMinutes", raw: string): boolean {
  const n = Number(raw);
  if (!Number.isFinite(n) || n < 0) return false;
  const v = Math.round(n);
  const c = resolveClock(ag);
  if (part === "gameLengthMinutes") {
    const first = Math.floor(v / 2);
    stampClock(ag, { ...c, firstHalfMinutes: first, secondHalfMinutes: v - first });
    return true;
  }
  if (part === "firstHalfMinutes" || part === "secondHalfMinutes") {
    if (v < 1) return false;
    stampClock(ag, { ...c, [part]: v });
    return true;
  }
  stampClock(ag, { ...c, [part]: v });
  return true;
}

export function occupyWindows(
  kickMinutes: number,
  c: GameClock,
): { warmup: number; end: number; vacate: number } {
  const len = onClockMinutes(c);
  return {
    warmup: kickMinutes - c.warmupMinutes,
    end: kickMinutes + len,
    vacate: kickMinutes + len + c.vacateMinutes,
  };
}

export function saturdaySlotCount(c: GameClock, windowStart = 8 * 60, windowEnd = 18 * 60): number {
  const block = Math.max(1, onClockMinutes(c) + c.vacateMinutes);
  return Math.max(0, Math.floor((windowEnd - windowStart) / block));
}

export function clockLivePhrase(bracket: string, c: GameClock): string {
  const play = playMinutes(c);
  const on = onClockMinutes(c);
  const slots = saturdaySlotCount(c);
  return `${bracket} ${play} play · ${on} on the clock · ${slots} slots / pitch`;
}
