import type { League, OpenDay, PlayingWeek, SpecialDate } from "./model";
import {
  addDays,
  formatClockShort,
  inferYear,
  parseHumanDate,
  parseIso,
  saturdaysInclusive,
  thanksgivingSaturday,
  weekBounds,
  weekdayName,
} from "./dates";

export const DEFAULT_OPEN_START = 8 * 60;
export const DEFAULT_OPEN_END = 18 * 60;

export function seasonYear(league: League): number {
  return inferYear(league.season.title || league.season.headerTitle, 2026);
}

export function playingSaturdays(league: League): string[] {
  const listed = league.season.openDays;
  if (listed?.length) return listed.filter((d) => d.open).map((d) => d.dateIso).sort();
  const first = league.season.firstIso;
  const last = league.season.lastIso;
  if (!first || !last) return [];
  return saturdaysInclusive(first, last, league.season.weekStarts || "Saturday");
}

function defaultStart(league: League): number {
  return league.season.defaultOpenStart ?? DEFAULT_OPEN_START;
}

function defaultEnd(league: League): number {
  return league.season.defaultOpenEnd ?? DEFAULT_OPEN_END;
}

function byeIsoSet(league: League): Set<string> {
  const set = new Set<string>();
  for (const s of league.season.specials) {
    if (s.kind === "bye" && s.iso) set.add(s.iso);
  }
  return set;
}

/** Seed Saturday game days from the season window. Keeps hand-toggled weekdays in range. */
export function ensureOpenDays(league: League): OpenDay[] {
  const first = league.season.firstIso;
  const last = league.season.lastIso;
  if (!first || !last) {
    league.season.openDays = league.season.openDays || [];
    return league.season.openDays;
  }
  if (league.season.defaultOpenStart == null) league.season.defaultOpenStart = DEFAULT_OPEN_START;
  if (league.season.defaultOpenEnd == null) league.season.defaultOpenEnd = DEFAULT_OPEN_END;
  const sats = saturdaysInclusive(first, last, league.season.weekStarts || "Saturday").filter(
    (d) => d >= first && d <= last,
  );
  const satSet = new Set(sats);
  const byes = byeIsoSet(league);
  const have = new Map((league.season.openDays || []).map((d) => [d.dateIso, d]));
  const next: OpenDay[] = [];
  for (const iso of sats) {
    const old = have.get(iso);
    next.push(
      old || {
        dateIso: iso,
        open: !byes.has(iso),
        startMinutes: defaultStart(league),
        endMinutes: defaultEnd(league),
      },
    );
  }
  for (const row of have.values()) {
    if (satSet.has(row.dateIso)) continue;
    if (row.dateIso < first || row.dateIso > last) continue;
    next.push(row);
  }
  next.sort((a, b) => a.dateIso.localeCompare(b.dateIso));
  league.season.openDays = next;
  return next;
}

export function openHours(league: League, dateIso: string): { startMinutes: number; endMinutes: number } | null {
  const row = (league.season.openDays || []).find((d) => d.dateIso === dateIso);
  if (row) return row.open ? { startMinutes: row.startMinutes, endMinutes: row.endMinutes } : null;
  const first = league.season.firstIso;
  const last = league.season.lastIso;
  if (!first || !last || dateIso < first || dateIso > last) return null;
  if (weekdayName(dateIso) !== "saturday") return null;
  return { startMinutes: defaultStart(league), endMinutes: defaultEnd(league) };
}

export function ensureGameDay(league: League, dateIso: string): OpenDay | null {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(dateIso)) return null;
  ensureOpenDays(league);
  const first = league.season.firstIso;
  const last = league.season.lastIso;
  if (first && last && (dateIso < first || dateIso > last)) return null;
  let row = (league.season.openDays || []).find((d) => d.dateIso === dateIso);
  if (!row) {
    row = {
      dateIso,
      open: true,
      startMinutes: defaultStart(league),
      endMinutes: defaultEnd(league),
    };
    league.season.openDays = [...(league.season.openDays || []), row].sort((a, b) => a.dateIso.localeCompare(b.dateIso));
    return row;
  }
  row.open = true;
  return row;
}

export function closeGameDay(league: League, dateIso: string): OpenDay | null {
  ensureOpenDays(league);
  const row = (league.season.openDays || []).find((d) => d.dateIso === dateIso);
  if (!row) return null;
  row.open = false;
  return row;
}

export function toggleOpenDay(league: League, dateIso: string): OpenDay | null {
  const row = (league.season.openDays || []).find((d) => d.dateIso === dateIso);
  if (row?.open) return closeGameDay(league, dateIso);
  return ensureGameDay(league, dateIso);
}

export function setDayHours(league: League, dateIso: string, startMinutes: number, endMinutes: number): OpenDay | null {
  if (startMinutes < 0 || endMinutes > 24 * 60 || endMinutes <= startMinutes) return null;
  ensureOpenDays(league);
  let row = (league.season.openDays || []).find((d) => d.dateIso === dateIso);
  if (!row) {
    row = { dateIso, open: true, startMinutes, endMinutes };
    league.season.openDays = [...(league.season.openDays || []), row].sort((a, b) => a.dateIso.localeCompare(b.dateIso));
    return row;
  }
  row.startMinutes = startMinutes;
  row.endMinutes = endMinutes;
  row.open = true;
  return row;
}

export function setDefaultOpenHours(league: League, startMinutes: number, endMinutes: number): boolean {
  if (startMinutes < 0 || endMinutes > 24 * 60 || endMinutes <= startMinutes) return false;
  league.season.defaultOpenStart = startMinutes;
  league.season.defaultOpenEnd = endMinutes;
  return true;
}

export function applyHoursToAllOpenDays(league: League): number {
  ensureOpenDays(league);
  const start = defaultStart(league);
  const end = defaultEnd(league);
  let n = 0;
  for (const d of league.season.openDays || []) {
    if (!d.open) continue;
    d.startMinutes = start;
    d.endMinutes = end;
    n++;
  }
  return n;
}

export function hoursPhrase(startMinutes: number, endMinutes: number): string {
  return `${formatClockShort(startMinutes)}–${formatClockShort(endMinutes)}`;
}

export function openDaysLine(league: League): string {
  ensureOpenDays(league);
  const days = league.season.openDays || [];
  const open = days.filter((d) => d.open);
  const closed = days.filter((d) => !d.open);
  if (!open.length) return "No game days yet — tap a Saturday on the calendar.";
  const start = defaultStart(league);
  const end = defaultEnd(league);
  const odd = open.filter((d) => d.startMinutes !== start || d.endMinutes !== end).length;
  const closedBit = closed.length ? ` · ${closed.length} closed` : "";
  const oddBit = odd ? ` · ${odd} with custom hours` : "";
  return `${open.length} game day${open.length === 1 ? "" : "s"} · grass ${hoursPhrase(start, end)}${oddBit}${closedBit}`;
}

export function calendarMonths(league: League): { year: number; month: number; label: string }[] {
  const first = league.season.firstIso;
  const last = league.season.lastIso;
  if (!first || !last) return [];
  const a = parseIso(first);
  const b = parseIso(last);
  const out: { year: number; month: number; label: string }[] = [];
  const names = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
  let y = a.getUTCFullYear();
  let m = a.getUTCMonth();
  const endY = b.getUTCFullYear();
  const endM = b.getUTCMonth();
  while (y < endY || (y === endY && m <= endM)) {
    out.push({ year: y, month: m, label: `${names[m]} ${y}` });
    m += 1;
    if (m > 11) {
      m = 0;
      y += 1;
    }
  }
  return out;
}

export function byeIsos(league: League): Set<string> {
  const year = seasonYear(league);
  const set = new Set<string>();
  for (const s of league.season.specials) {
    if (s.kind !== "bye") continue;
    if (s.iso) {
      // if bye is a weekday, snap to that week's Saturday in a Saturday-start season
      set.add(snapToSaturday(s.iso, league.season.weekStarts));
      continue;
    }
    if (/thanksgiving/i.test(s.raw + " " + (s.note || ""))) {
      const t = thanksgivingSaturday(year);
      const sats = playingSaturdays(league);
      const inRange = sats.find((d) => d === t) || sats.filter((d) => d <= t).pop();
      if (inRange) set.add(inRange);
    }
  }
  return set;
}

export function rainCheckIsos(league: League): string[] {
  return league.season.specials
    .filter((s) => s.kind === "rain-check" && s.iso)
    .map((s) => s.iso!) ;
}

function snapToSaturday(isoDate: string, weekStarts: string): string {
  if (weekdayName(isoDate) === "saturday") return isoDate;
  const { start } = weekBounds(isoDate, weekStarts || "Saturday");
  let d = start;
  for (let i = 0; i < 7; i++) {
    if (weekdayName(d) === "saturday") return d;
    d = addDays(d, 1);
  }
  return isoDate;
}

export function weeks(league: League): PlayingWeek[] {
  const sats = playingSaturdays(league);
  const byes = byeIsos(league);
  const rains = new Set(rainCheckIsos(league));
  const startName = league.season.weekStarts || "Saturday";
  const out: PlayingWeek[] = sats.map((sat) => {
    const { start, end } = weekBounds(sat, startName);
    const isBye = byes.has(sat);
    return {
      startIso: start,
      endIso: end,
      label: sat,
      kind: isBye ? "bye" : "playing",
      saturdays: [sat],
    };
  });
  for (const r of rains) {
    if (out.some((w) => w.saturdays.includes(r))) continue;
    const { start, end } = weekBounds(r, startName);
    out.push({
      startIso: start,
      endIso: end,
      label: r,
      kind: "rain-check",
      saturdays: [r],
    });
  }
  out.sort((a, b) => a.label.localeCompare(b.label));
  return out;
}

export function owedGames(league: League): number {
  return weeks(league).filter((w) => w.kind === "playing").length;
}

export function resolveSpecial(raw: string, kind: SpecialDate["kind"], year: number): SpecialDate {
  const note = raw;
  if (/thanksgiving/i.test(raw) && kind === "bye") {
    return { kind, raw, iso: undefined, note };
  }
  const iso = parseHumanDate(raw, year);
  if (iso) return { kind, raw, iso, note };
  return { kind, raw, note };
}
