function parent(first: string, last: string, phone: string, coachOf: string[] = [], assistantOf: string[] = []): Parent {
  return { first, last, phone, coachOf, assistantOf };
}

function kids(...rows: [string, string, string, string][]): Family["children"] {
  return rows.map(([first, last, bracket, team]) => ({ first, last, bracket, team }));
}

function team(partial: Omit<Team, "awayDesired" | "guestDesired" | "willNotPlay" | "willNotTravelTo" | "players"> & Partial<Team>): Team {
  return {
    awayDesired: 0,
    guestDesired: 0,
    willNotPlay: [],
    willNotTravelTo: [],
    players: [],
    ...partial,
  };
}

function names(n: number, prefix: string, last: string): { name: string }[] {
  const firsts = ["Sam", "Riley", "Casey", "Morgan", "Quinn", "Jamie", "Drew", "Avery", "Reese", "Parker", "Rowan", "Skyler"];
  return Array.from({ length: n }, (_, i) => ({ name: `${prefix}${firsts[i % firsts.length]} ${last}` }));
}

